(function(){"use strict";chrome.runtime.onInstalled.addListener(e=>{e.reason==="install"&&chrome.storage.sync.set({enabled:!0,autoScan:!0,maxResults:10,scanInterval:600},()=>{console.log("[mapshort] 初回インストール: デフォルト設定を保存しました")})}),chrome.runtime.onMessage.addListener((e,a,r)=>{if(e.type==="FETCH_YOUTUBE_SEARCH"){const o=typeof e.query=="string"?e.query:"";if(!o){r({ok:!1,error:"検索語が空です"});return}const u=`https://www.youtube.com/results?search_query=${encodeURIComponent(o)}`;return fetch(u,{headers:{Accept:"text/html","Accept-Language":"ja"}}).then(async t=>{if(!t.ok){r({ok:!1,error:`YouTube検索ページを取得できませんでした: ${t.status}`});return}r({ok:!0,html:await t.text()})}).catch(t=>{r({ok:!1,error:`YouTube検索ページの取得に失敗しました: ${t instanceof Error?t.message:"network error"}`})}),!0}return e.type==="CLEAR_CACHE"?(chrome.tabs.query({url:["*://www.google.com/maps/*","*://maps.google.com/*"]},o=>{o.forEach(u=>{u.id!=null&&chrome.tabs.sendMessage(u.id,{type:"CLEAR_CACHE"}).catch(()=>{})}),r({ok:!0})}),!0):!1})})();
